  await waitFor(()=>evaluate(`document.querySelector('[data-exam-clock] [role=timer]').textContent!==${JSON.stringify(adminClock)}`),3000);
  await panelScreenshot('[data-exam-clock]','teacher-waiting-clock-desktop.png');
  await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});await noOverflow();await panelScreenshot('[data-exam-clock]','teacher-waiting-clock-mobile.png');
  await send('Emulation.setDeviceMetricsOverride',{width:1440,height:1100,deviceScaleFactor:1,mobile:false});
