  await waitFor(()=>evaluate(`Math.abs(Date.parse(document.querySelector('[data-exam-timing-form] [name=scheduled_at]')?.value+'+07:00')-${Date.parse(shifted.starts_at)})<1000`),10000);
  await navigate(base+'/admin?section=exam');
  assert.equal(await evaluate(`!!document.querySelector('[data-exam-card="${created.id}"] [role=timer]') && !document.querySelector('[data-exam-monitor="${created.id}"]')`),true);
