  const judged=await fetch(base+'/api/student/programming/submit',{method:'POST',headers:{Cookie:'css_session='+fixture.student,Origin:base},body:upload});assert.equal(judged.status,200,await judged.text());
  await waitFor(()=>evaluate("document.querySelector('[data-monitor-accepted=QA001]')?.textContent==='1/1 bài'"),14000);
